#!/usr/bin/env python3
# Check commit messages against the Conventional Commits rules in AGENTS.md.
# Used by .githooks/commit-msg (one message file) and by CI (a revision range).
import argparse
from pathlib import Path
import re
import subprocess
import sys
import unicodedata

TYPES = ("feat", "fix", "refactor", "perf", "test", "docs", "build", "ci", "chore", "revert")
HEADER = re.compile(rf"^(?P<type>{'|'.join(TYPES)})(\((?P<scope>[a-z0-9][a-z0-9._/-]*)\))?(?P<breaking>!)?: (?P<description>\S.*)$")
# Messages generated by git itself or by the GitHub merge button.
GENERATED = re.compile(r'^(Merge |Revert "|(fixup|squash|amend)! )')
MAX_HEADER = 100


def foreign_letters(text):
    return sorted({ch for ch in text if ord(ch) > 0x7F and unicodedata.category(ch).startswith("L")
                   and not unicodedata.name(ch, "").startswith("LATIN")})


def check(message):
    lines = [line for line in message.splitlines() if not line.startswith("#")]
    while lines and not lines[0].strip():
        lines.pop(0)
    if not lines:
        return ["empty commit message"]
    header = lines[0]
    if GENERATED.match(header):
        return []
    problems = []
    match = HEADER.match(header)
    if not match:
        problems.append(f"header must be '<type>(<scope>): <description>' with type in {', '.join(TYPES)}: {header!r}")
    else:
        if header.endswith("."):
            problems.append("header must not end with a period")
        if match["description"][0].isupper():
            problems.append("description must start with a lowercase letter")
    if len(header) > MAX_HEADER:
        problems.append(f"header is {len(header)} characters; the limit is {MAX_HEADER}")
    if len(lines) > 1 and lines[1].strip():
        problems.append("header must be followed by a blank line")
    footer_breaking = any(line.startswith("BREAKING CHANGE:") for line in lines)
    if footer_breaking and match and not match["breaking"]:
        problems.append("a BREAKING CHANGE footer needs '!' before the colon in the header")
    if match and match["breaking"] and not footer_breaking:
        problems.append("a '!' header needs a 'BREAKING CHANGE:' footer explaining it")
    letters = foreign_letters("\n".join(lines))
    if letters:
        problems.append("commit messages are written in English; found non-Latin letters: " + " ".join(letters[:8]))
    return problems


def range_messages(revision_range):
    out = subprocess.check_output(["git", "log", "--no-merges", "--format=%H%x00%B%x01", revision_range], text=True)
    for record in out.split("\x01"):
        if not record.strip():
            continue
        commit, _, body = record.strip("\n").partition("\x00")
        yield commit[:12], body


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    source = parser.add_mutually_exclusive_group(required=True)
    source.add_argument("message_file", nargs="?", help="commit message file, as passed to the commit-msg hook")
    source.add_argument("--range", dest="revision_range", help="git revision range such as origin/dev..HEAD")
    args = parser.parse_args()

    if args.revision_range:
        try:
            items = list(range_messages(args.revision_range))
        except subprocess.CalledProcessError:
            print(f"commit-msg: cannot list the commits in {args.revision_range!r}", file=sys.stderr)
            return 2
    else:
        items = [("message", Path(args.message_file).read_text(encoding="utf-8", errors="replace"))]

    failed = False
    for name, message in items:
        for problem in check(message):
            failed = True
            print(f"commit-msg: {name}: {problem}", file=sys.stderr)
    if failed:
        print("See section 2 of AGENTS.md for the commit format.", file=sys.stderr)
        return 1
    return 0


if __name__ == "__main__":
    sys.exit(main())
